{
  "findings": [
    {
      "check_id": "CKV_GCP_79",
      "title": "Cloud SQL uses an outdated PostgreSQL major version",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The instance is configured with PostgreSQL 13 rather than the latest Cloud SQL PostgreSQL major version, increasing exposure to version-specific vulnerabilities and earlier end-of-support."
    },
    {
      "check_id": "CKV_GCP_110",
      "title": "pgAudit is not enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable cloudsql.enable_pgaudit, limiting database-level audit visibility for sensitive trading data and privileged activity."
    },
    {
      "check_id": "CKV_GCP_51",
      "title": "Checkpoint logging is not enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_checkpoints flag is absent, reducing visibility into checkpoint activity that can be relevant during operational or security investigations."
    },
    {
      "check_id": "CKV_GCP_52",
      "title": "Connection logging is disabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_connections flag is explicitly set to off, preventing successful connection attempts from being recorded for audit and investigation."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "Disconnection logging is not enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_disconnections flag is absent, preventing complete tracking of database session lifecycles."
    },
    {
      "check_id": "CKV_GCP_108",
      "title": "Client hostname logging is not enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_hostname flag is absent, reducing the contextual information available when investigating database connections."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Lock-wait logging is not enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_lock_waits flag is absent, limiting detection and investigation of lock contention or potentially abusive long-running transactions."
    },
    {
      "check_id": "CKV_GCP_109",
      "title": "Database error logging level is not explicitly configured",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_min_messages flag is absent, so the required ERROR-level database event logging is not explicitly enforced."
    },
    {
      "check_id": "CKV_GCP_111",
      "title": "SQL statement logging is not enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_statement flag is absent, limiting audit visibility into SQL commands executed against the trading database."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "SSL is not required for database connections",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "Although the instance only uses a private address, its IP configuration does not require SSL, allowing unencrypted database connections within the private network."
    },
    {
      "check_id": "CKV2_GCP_13",
      "title": "Statement duration logging is not enabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The log_duration flag is absent, preventing statement execution duration from being consistently captured for monitoring and investigation."
    },
    {
      "check_id": "CKV_GCP_68",
      "title": "Cloud SQL deletion protection is disabled",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "Deletion protection is explicitly disabled, increasing the risk that the trading database could be accidentally or maliciously destroyed through Terraform."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"trading_database\" {\n  name                = \"real-time-financial-trading-platform-database-trading\"\n  database_version    = \"POSTGRES_17\"\n  region              = var.region\n  deletion_protection = true\n\n  settings {\n    tier = \"db-n1-standard-2\"\n\n    ip_configuration {\n      ipv4_enabled    = false\n      private_network = google_compute_network.trading_platform_vpc.id\n      require_ssl     = true\n    }\n\n    database_flags {\n      name  = \"cloudsql.enable_pgaudit\"\n      value = \"on\"\n    }\n\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n\n    database_flags {\n      name  = \"log_hostname\"\n      value = \"on\"\n    }\n\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n\n    database_flags {\n      name  = \"log_min_messages\"\n      value = \"error\"\n    }\n\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n\n    database_flags {\n      name  = \"log_duration\"\n      value = \"on\"\n    }\n\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n  }\n\n  depends_on = [google_service_networking_connection.private_vpc_connection]\n}\n",
  "fix_summary": "Upgraded the PostgreSQL major version, enabled deletion protection, required SSL, and added the applicable PostgreSQL auditing and logging flags. Existing private networking, backups, point-in-time recovery, dependencies, and resource structure were retained."
}
